INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('a80d565d-c6d9-4f86-b941-cec6e83d1841', 'b2b2b2b2-3030-4000-8000-000000000002', 30, 'Dia 30 — Inteiro', 'Semana 4: Integrar', '{"pch": "Sara os quebrantados de cora\u00e7\u00e3o\u2026 e liga-lhes as feridas. Voc\u00ea n\u00e3o est\u00e1 quebrado. Est\u00e1 sendo restaurado.", "verse": "Sl 147,3", "lectio": "Leia Sl 147,1-7. Deus conta as estrelas e sara os cora\u00e7\u00f5es.", "practice": "Releia suas reflex\u00f5es dos 30 dias. Escreva uma carta de gratid\u00e3o a si mesmo.", "question": "Quem voc\u00ea se tornou atrav\u00e9s da dor?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;